package store

import (
	"reflect"
	"testing"

	"github.com/studoo-app/watchoo/internal/store/db"
)

// TestPublicAPIHidesGeneratedTypes checks the architecture rule "the types generated by sqlc do not
// leave internal/store": no exported method of *Store, nor any exported function of the package
// (list below, to be completed), receives or returns a type of the db package (even inside a
// pointer, a list…).
func TestPublicAPIHidesGeneratedTypes(t *testing.T) {
	check := func(name string, fn reflect.Type) {
		for i := range fn.NumIn() {
			if usesGenerated(fn.In(i)) {
				t.Errorf("%s receives a type generated by sqlc: %s", name, fn.In(i))
			}
		}
		for i := range fn.NumOut() {
			if usesGenerated(fn.Out(i)) {
				t.Errorf("%s returns a type generated by sqlc: %s", name, fn.Out(i))
			}
		}
	}

	st := reflect.TypeFor[*Store]()
	if st.NumMethod() == 0 {
		t.Fatal("no exported method found on *Store")
	}
	for i := range st.NumMethod() {
		m := st.Method(i)
		check("Store."+m.Name, m.Type)
	}
	for name, fn := range map[string]any{
		"Open": Open, "FormatTime": FormatTime, "ParseTime": ParseTime, "CreateDBFile": CreateDBFile,
	} {
		check(name, reflect.TypeOf(fn))
	}
}

// usesGenerated reports whether the type t is a type of the db package, or contains one (pointer,
// slice, array, map, channel).
func usesGenerated(t reflect.Type) bool {
	switch t.Kind() {
	case reflect.Pointer, reflect.Slice, reflect.Array, reflect.Chan:
		return usesGenerated(t.Elem())
	case reflect.Map:
		return usesGenerated(t.Key()) || usesGenerated(t.Elem())
	}
	return t.PkgPath() == reflect.TypeFor[db.Queries]().PkgPath()
}
